import{_ as u,a0 as p,w as a,s as r,ao as l,I as o,x as t,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"Linux 的逆襲 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 的逆襲 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 的逆襲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 的逆襲 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160803 The revenge of Linux","title":"Linux 的逆襲","tag":"201609","desc":""},"relativePath":"201609/20160803 The revenge of Linux.md","filePath":"[post].md"}'),x={name:"201609/20160803 The revenge of Linux.md"};function L(d,e,f,m,T,g){const n=p("Link");return a(),r("div",null,[e[13]||(e[13]=l('<h1 id="linux-的逆襲" tabindex="-1">Linux 的逆襲 <a class="header-anchor" href="#linux-的逆襲" aria-label="Permalink to “Linux 的逆襲”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/penguin%20swimming.jpg?itok=mfhEdRdM" alt=""></p><p>Linux 系統在早期的時候被人們嘲笑，它什麼也幹不了。而現在，Linux 無處不在！</p><p>我當時還是個在巴西學習計算機工程的大三學生，並同時在一個全球審計和顧問公司兼職系統管理員。公司決定用 Oracle 資料庫開發一些企業資源計劃（ERP）軟件。因此，我得以在 Digital UNIX OS (DEC Alpha) 進行訓練，這個訓練顛覆了我的三觀。</p><p>UNIX 系統非常的強大，而且給予了我們對機器上包括存儲系統、網絡、應用和其他一切的絕對控制權。</p><p>我開始在 ksh 和 Bash 裏編寫大量的腳本讓系統進行自動備份、文件傳輸、提取轉換加載（ETL）操作、自動化 DBA 日常工作，還為各種不同的項目創建了許多服務。此外，調整資料庫和操作系統的工作讓我更好的理解了如何讓服務器以最佳方式運行。在那時，我在自己的個人電腦上使用的是 Windows 95 系統，而我非常想要在我的個人電腦裏放進一個 Digital UNIX，或者哪怕是 Solaris 或 HP-UX 也行，但是那些 UNIX 系統都得在特定的硬件才能上運行。我閲讀了所有的系統文檔，還找過其它的書籍以求獲得更多的信息，也在我們的開發環境裏對這些瘋狂的想法進行了實驗。</p><p>後來在大學裏，我從我的同事那聽説了 Linux。我那時非常激動的從還在用撥號方式連接的因特網上下載了它。在我的正宗的個人電腦裏裝上 UNIX 這類系統的這個想法真是太酷了！</p><p>Linux 不同於 UNIX 系統，它設計用來在各種常見個人電腦硬件上運行，在起初，讓它開始工作確實有點困難，Linux 針對的用户羣只有系統管理員和極客們。我為了讓它能運行，甚至用 C 語言修改了驅動軟件。我之前使用 UNIX 的經歷讓我在編譯 Linux 內核，排錯這些過程中非常的順手。由於它不同於那些只適合特定硬件配置的封閉系統，所以讓 Linux 跟各種意料之外的硬件配置一起工作真的是件非常具有挑戰性的事。</p><p>我曾見過 Linux 在數據中心獲得一席之地。一些具有冒險精神的系統管理員使用它來幫他們完成每天監視和管理基礎設施的工作，隨後，Linux 作為 DNS 和 DHCP 服務器、打印管理和文件服務器等贏得了更多的使用。企業曾對 Linux 有着很多顧慮（恐懼，不確定性，懷疑(FUD:fear, uncertainty and doubt)）和詬病：誰是它的擁有者？由誰來支持它？有適用於它的應用嗎？</p><p>但現在看來，Linux 在各個地方進行着逆襲！從開發者的個人電腦到大企業的服務器；我們能在智能手機、智能手錶以及像樹莓派這樣的物聯網（IoT）設備裏找到它。甚至 Mac OS X 有些命令跟我們所熟悉的命令一樣。微軟在製造它自己的發行版，在 Azure 上運行，然後…… Windows 10 要裝備 Bash。</p><p>有趣的是 IT 市場會不斷地創造並迅速的用新技術替代，但是我們所掌握的 Digital UNIX、HP-UX 和 Solaris 這些舊系統的知識還依然有效並跟 Linux 息息相關，不論是為了工作還是玩。現在我們能完全的掌控我們的系統，並使它發揮最大的效用。此外，Linux 有個充滿熱情的社區。</p><p>我真的建議想在計算機方面發展的年輕人學習 Linux，不論你處於 IT 界裏的哪個分支。如果你深入瞭解了一個普通的家用個人電腦是如何工作的，你就可以以基本相同的方式來面對任何機器。你可以通過 Linux 學習最基本的計算機知識，並通過它建立能在 IT 界任何地方都有用的能力！</p><hr>',13)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(n,{href:"https://opensource.com/life/16/8/revenge-linux"},{default:s(()=>[...e[0]||(e[0]=[t("https://opensource.com/life/16/8/revenge-linux",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),i(n,{href:"https://opensource.com/users/danielscarvalho"},{default:s(()=>[...e[2]||(e[2]=[t("Daniel Carvalho",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),i(n,{href:"https://github.com/H-mudcup"},{default:s(()=>[...e[3]||(e[3]=[t("H-mudcup",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),i(n,{href:"https://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const N=u(x,[["render",L]]);export{I as __pageData,N as default};
